1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"math"
10		"sort"
11		"strings"
12	)
13	
14	// Reason constants for clusters that cannot enter a release plan.
15	const (
16		ReasonDisabled          = "集群已停用"
17		ReasonExcludeMatched    = "命中排除条件"
18		ReasonIncludeNotMatched = "未命中包含条件"
19	)
20	
21	// LabelCondition is a set of exact key-value matches; all must match.
22	type LabelCondition map[string]string
23	
24	// Cluster is a candidate target for a release.
25	type Cluster struct {
26		ID       string
27		Disabled bool
28		Tags     map[string]string
29	}
30	
31	// ReleasePlanInput describes an application release to plan offline.
32	type ReleasePlanInput struct {
33		App       string
34		Revision  string
35		Image     string
36		BatchSize int
37		Clusters  []Cluster
38		Include   []LabelCondition
39		Exclude   []LabelCondition
40		// SpreadBy, when non-empty, names a cluster tag whose value identifies a
41		// fault domain; each batch then contains at most one cluster per domain.
42		SpreadBy string
43	}
44	
45	// AppInfo identifies the application being released.
46	type AppInfo struct {
47		Name     string `json:"name"`
48		Revision string `json:"revision"`
49		Image    string `json:"image"`
50	}
51	
52	// Batch is a sequentially numbered group of cluster IDs.
53	type Batch struct {
54		Index    int      `json:"index"`
55		Clusters []string `json:"clusters"`
56	}
57	
58	// ExcludedCluster explains why a cluster is not in the plan.
59	type ExcludedCluster struct {
60		ID     string `json:"id"`
61		Reason string `json:"reason"`
62	}
63	
64	// ReleasePlan is the deterministic offline release plan.
65	type ReleasePlan struct {
66		App      AppInfo           `json:"app"`
67		Batches  []Batch           `json:"batches"`
68		Excluded []ExcludedCluster `json:"excluded"`
69	}
70	
71	// ParseReleaseInput reads a release plan document and validates its fields.
72	// Every string in the document — member names and values, in known fields
73	// and in unknown extra fields — must be legal text: invalid UTF-8 bytes and
74	// \uXXXX escapes naming an unpaired surrogate are rejected first, before any
75	// decoded string can be silently rewritten to "�" and compared. Every JSON
76	// object in the document — including unknown fields and their nested
77	// objects — must then have distinct member names; a name appearing twice
78	// (even with the same value, or via equivalent Unicode escapes) is rejected
79	// before any business validation runs. The document's structural nesting
80	// is capped at maxJSONNestingDepth levels in every field, known or not; a
81	// document that opens a 10001st level is rejected with
82	// errJSONDepthExceeded before any business validation or planning runs.
83	func ParseReleaseInput(data []byte) (ReleasePlanInput, error) {
84		if err := checkStrictText(data); err != nil {
85			return ReleasePlanInput{}, err
86		}
87		if err := checkDuplicateMembers(data); err != nil {
88			return ReleasePlanInput{}, err
89		}
90		dec := json.NewDecoder(bytes.NewReader(data))
91		dec.UseNumber()
92		var doc map[string]any
93		if err := dec.Decode(&doc); err != nil {
94			if isJSONDepthError(err) {
95				return ReleasePlanInput{}, errJSONDepthExceeded
96			}
97			return ReleasePlanInput{}, fmt.Errorf("JSON 格式错误: %w", err)
98		}
99		if dec.More() {
100			return ReleasePlanInput{}, errors.New("JSON 格式错误: 文档包含多余内容")
101		}
102		return buildReleaseInput(doc)
103	}
104	
105	// duplicateMemberError reports a JSON object whose member name appears more
106	// than once. Path is a JSONPath-style location that points at the object
107	// owning the duplicate (the duplicate member name itself is reported
108	// separately in field): "$" for the document root, "$.clusters[1]" for a
109	// cluster, "$.clusters[0].tags" for a tag object,
110	// "$.include[2]" / "$.exclude[1]" for a condition, and "$.foo.bar[0]" for
111	// objects nested inside unknown fields. A member name that is not a plain
112	// identifier is wrapped in brackets around a JSON string, so that characters
113	// in the name can never be read as hierarchy or an array index: a top-level
114	// member "meta.info" is at $["meta.info"] (distinct from the nested object
115	// $.meta.info), "zone[0]" stays one whole name at $["zone[0]"], and names
116	// that are empty or contain quotes, backslashes or control characters are
117	// rendered as decodable JSON strings such as $[""] or $["a\nb"].
118	type duplicateMemberError struct {
119		field string
120		path  string
121	}
122	
123	func (e *duplicateMemberError) Error() string {
124		return fmt.Sprintf("JSON 对象存在重复成员: 字段 %q 重复出现于 %s", e.field, e.path)
125	}
126	
127	// checkDuplicateMembers walks every JSON object in data and rejects objects
128	// with duplicate member names. Names are compared after JSON decoding, so
129	// "env" and "env" are the same name while "env" and "ENV", or
130	// " env" and "env", are different. The first duplicate encountered in file
131	// order is reported: the walk is depth-first in document order, so the
132	// second occurrence that appears earliest wins, regardless of value type.
133	//
134	// The check is a policy over the shared structural walk (jsonwalk.go): the
135	// walker recognizes the nesting, decodes the member names and tracks each
136	// object's location; this check only keeps the seen-name set of each object.
137	// A document the walk cannot fully vouch for — an unrecognized structure,
138	// trailing content, or a malformed number the walk stopped on — is handed to
139	// the encoding/json walk, which reports the established format error (and
140	// any duplicate preceding the malformation) with the existing wording.
141	func checkDuplicateMembers(data []byte) error {
142		dup, recognized := scanDuplicateMembers(data)
143		// The nesting limit is a verdict by itself: it holds whether or not the
144		// document is otherwise well-formed and needs no json.Valid confirmation,
145		// so a too-deep document stops here instead of being scanned twice.
146		if errors.Is(dup, errJSONDepthExceeded) {
147			return dup
148		}
149		// json.Valid confirms the whole document — including every number the
150		// walk grammar-checked and any trailing content — is one well-formed
151		// JSON value, so a completed walk's verdict can be trusted directly.
152		// Legal numbers beyond float64 range (e.g. 1e400) are valid JSON and
153		// pass; whether a number is acceptable for a given field is decided
154		// later by business validation.
155		if recognized && json.Valid(data) {
156			return dup
157		}
158		return checkJSONFormatAndDuplicates(data)
159	}
160	
161	// scanDuplicateMembers runs the duplicate-member policy over the shared
162	// structural walk. It reports the first duplicate in file order — the walk
163	// is depth-first in document order, so the second occurrence that appears
164	// earliest wins — and whether the walk recognized the document's structure
165	// (no errUndecided and no text problem, both of which leave the verdict to
166	// the decoder walk). recognized does not by itself mean the document is
167	// well-formed JSON: the caller confirms that with json.Valid.
168	func scanDuplicateMembers(data []byte) (dup error, recognized bool) {
169		// Each entered object's frame id is unique, so the seen-name sets are
170		// keyed by the owning object's id; the walk needs no enter/exit events
171		// for them.
172		seen := make(map[uint64]map[string]struct{})
173		var w *jsonWalker
174		w = &jsonWalker{data: data, onMember: func(ownerID uint64, name string) error {
175			set := seen[ownerID]
176			if set == nil {
177				set = make(map[string]struct{})
178				seen[ownerID] = set
179			}
180			if _, ok := set[name]; ok {
181				dup = &duplicateMemberError{field: name, path: w.framePathByID(ownerID)}
182				return dup
183			}
184			set[name] = struct{}{}
185			return nil
186		}}
187		if err := w.walk(); err != nil && dup == nil {
188			if errors.Is(err, errJSONDepthExceeded) {
189				return err, true
190			}
191			return nil, false
192		}
193		return dup, true
194	}
195	
196	// checkJSONFormatAndDuplicates is the encoding/json walk that documents the
197	// raw structural walk cannot recognize are handed to. It reports the JSON
198	// format error with the established wording — and a duplicate member when
199	// its second occurrence precedes the malformation — exactly as the duplicate
200	// check always has for such documents. The Token API enforces no nesting
201	// limit of its own, so the walk carries the same maxJSONNestingDepth
202	// counter: a malformed document that is also too deep (e.g. one with no
203	// closing brackets at all) is refused with errJSONDepthExceeded instead of
204	// recursing down the reader's call stack and reporting "unclosed" later.
205	func checkJSONFormatAndDuplicates(data []byte) error {
206		dec := json.NewDecoder(bytes.NewReader(data))
207		// Numbers are only walked past, never interpreted: UseNumber keeps legal
208		// JSON numbers beyond float64 range (e.g. 1e400) from being turned into an
209		// unmarshal-overflow error here. Whether a number is acceptable for a given
210		// field is decided later by business validation.
211		dec.UseNumber()
212		depth := 0
213		if err := walkJSONValue(dec, "$", &depth); err != nil {
214			return err
215		}
216		if _, err := dec.Token(); err != io.EOF {
217			if err == nil {
218				return errors.New("JSON 格式错误: 文档包含多余内容")
219			}
220			if isJSONDepthError(err) {
221				return errJSONDepthExceeded
222			}
223			return fmt.Errorf("JSON 格式错误: %w", err)
224		}
225		return nil
226	}
227	
228	// enterContainer enforces the shared nesting limit on the Token walk: the
229	// root container is level 1 and each entered object or array adds one,
230	// exactly as in the raw walker. It returns errJSONDepthExceeded at the
231	// 10001st level.
232	func enterContainer(depth *int) error {
233		*depth++
234		if *depth > maxJSONNestingDepth {
235			return errJSONDepthExceeded
236		}
237		return nil
238	}
239	
240	// leaveContainer marks one container closed.
241	func leaveContainer(depth *int) {
242		*depth--
243	}
244	
245	// walkJSONValue reads one complete JSON value whose first token has not been
246	// consumed yet. Together with walkJSONObject and walkJSONArray it is the
247	// decoding half of checkJSONFormatAndDuplicates: it only runs for documents
248	// the shared structural walk could not recognize, to report the format error
249	// (or an earlier duplicate) with the established wording.
250	func walkJSONValue(dec *json.Decoder, path string, depth *int) error {
251		tok, err := dec.Token()
252		if err != nil {
253			if err == io.EOF {
254				return errors.New("JSON 格式错误: 文档为空")
255			}
256			if isJSONDepthError(err) {
257				return errJSONDepthExceeded
258			}
259			return fmt.Errorf("JSON 格式错误: %w", err)
260		}
261		return walkJSONValueToken(dec, path, tok, depth)
262	}
263	
264	// walkJSONValueToken reads the remainder of a value given its first token.
265	func walkJSONValueToken(dec *json.Decoder, path string, tok json.Token, depth *int) error {
266		if d, ok := tok.(json.Delim); ok {
267			if err := enterContainer(depth); err != nil {
268				return err
269			}
270			switch d {
271			case '{':
272				return walkJSONObject(dec, path, depth)
273			case '[':
274				return walkJSONArray(dec, path, depth)
275			default:
276				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
277			}
278		}
279		return nil // scalar value (string, number, bool, null)
280	}
281	
282	func walkJSONObject(dec *json.Decoder, path string, depth *int) error {
283		defer leaveContainer(depth)
284		seen := make(map[string]struct{})
285		for {
286			tok, err := dec.Token()
287			if err != nil {
288				if err == io.EOF {
289					return errors.New("JSON 格式错误: 对象未闭合")
290				}
291				if isJSONDepthError(err) {
292					return errJSONDepthExceeded
293				}
294				return fmt.Errorf("JSON 格式错误: %w", err)
295			}
296			if d, ok := tok.(json.Delim); ok {
297				if d == '}' {
298					return nil
299				}
300				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
301			}
302			key, ok := tok.(string)
303			if !ok {
304				return errors.New("JSON 格式错误: 对象成员名必须是字符串")
305			}
306			if _, dup := seen[key]; dup {
307				return &duplicateMemberError{field: key, path: path}
308			}
309			seen[key] = struct{}{}
310			vtok, err := dec.Token()
311			if err != nil {
312				if err == io.EOF {
313					return errors.New("JSON 格式错误: 缺少成员值")
314				}
315				if isJSONDepthError(err) {
316					return errJSONDepthExceeded
317				}
318				return fmt.Errorf("JSON 格式错误: %w", err)
319			}
320			if err := walkJSONValueToken(dec, joinMemberPath(path, key), vtok, depth); err != nil {
321				return err
322			}
323		}
324	}
325	
326	func walkJSONArray(dec *json.Decoder, path string, depth *int) error {
327		defer leaveContainer(depth)
328		for i := 0; ; i++ {
329			tok, err := dec.Token()
330			if err != nil {
331				if err == io.EOF {
332					return errors.New("JSON 格式错误: 数组未闭合")
333				}
334				if isJSONDepthError(err) {
335					return errJSONDepthExceeded
336				}
337				return fmt.Errorf("JSON 格式错误: %w", err)
338			}
339			if d, ok := tok.(json.Delim); ok && d == ']' {
340				return nil
341			}
342			if err := walkJSONValueToken(dec, joinIndexPath(path, i), tok, depth); err != nil {
343				return err
344			}
345		}
346	}
347	
348	// isJSONDepthError reports whether err is encoding/json's own
349	// nesting-limit failure (Decode/Valid enforce it even though the Token
350	// API does not). The message is matched rather than a typed error,
351	// because the scanner's "exceeded max depth" SyntaxError is not exported
352	// as one.
353	func isJSONDepthError(err error) bool {
354		return err != nil && strings.Contains(err.Error(), "exceeded max depth")
355	}
356	
357	func buildReleaseInput(doc map[string]any) (ReleasePlanInput, error) {
358		app, err := requiredString(doc, "app")
359		if err != nil {
360			return ReleasePlanInput{}, err
361		}
362		revision, err := requiredString(doc, "revision")
363		if err != nil {
364			return ReleasePlanInput{}, err
365		}
366		image, err := requiredString(doc, "image")
367		if err != nil {
368			return ReleasePlanInput{}, err
369		}
370		batchSize, err := positiveInt(doc, "batchSize")
371		if err != nil {
372			return ReleasePlanInput{}, err
373		}
374		spreadBy, err := optionalSpreadBy(doc)
375		if err != nil {
376			return ReleasePlanInput{}, err
377		}
378		clusters, err := parseClusters(doc["clusters"])
379		if err != nil {
380			return ReleasePlanInput{}, err
381		}
382		include, err := parseConditions(doc, "include")
383		if err != nil {
384			return ReleasePlanInput{}, err
385		}
386		exclude, err := parseConditions(doc, "exclude")
387		if err != nil {
388			return ReleasePlanInput{}, err
389		}
390	
391		return ReleasePlanInput{
392			App:       app,
393			Revision:  revision,
394			Image:     image,
395			BatchSize: batchSize,
396			Clusters:  clusters,
397			Include:   include,
398			Exclude:   exclude,
399			SpreadBy:  spreadBy,
400		}, nil
401	}
402	
403	// optionalSpreadBy reads the optional "spreadBy" field: absent or an empty
404	// string disables fault-domain spreading; a non-string value or a string of
405	// only whitespace is rejected. The tag key is used exactly as written.
406	func optionalSpreadBy(doc map[string]any) (string, error) {
407		v, ok := doc["spreadBy"]
408		if !ok {
409			return "", nil
410		}
411		s, ok := v.(string)
412		if !ok {
413			return "", fmt.Errorf("字段 %q 必须是字符串", "spreadBy")
414		}
415		if err := checkSpreadBy(s); err != nil {
416			return "", err
417		}
418		return s, nil
419	}
420	
421	// checkSpreadBy rejects a spreadBy value that is neither empty nor a usable
422	// tag key: a string of only whitespace can never match a valid tag key.
423	func checkSpreadBy(s string) error {
424		if s != "" && strings.TrimSpace(s) == "" {
425			return fmt.Errorf("字段 %q 不能只含空白", "spreadBy")
426		}
427		return nil
428	}
429	
430	// ValidateReleaseInput checks that a release configuration is well-formed.
431	// Every string is first required to be legal UTF-8 — app, revision, image,
432	// spreadBy, every candidate's ID and tag keys/values (disabled and
433	// filtered-out candidates included), and every include/exclude condition's
434	// keys and values — because invalid bytes would later be rewritten to "�"
435	// while the plan is written as JSON and could merge two distinct identities
436	// or take part in label matching as an ordinary value. That text check runs
437	// before any business rule, in a fixed order (field order, then candidate
438	// and condition positions from zero, then keys in ascending order), so the
439	// one problem it reports never depends on map iteration. Business
440	// validation then runs as before: app/revision/image are non-empty,
441	// batchSize is a positive integer, spreadBy is empty or a usable tag key
442	// (not whitespace-only), cluster IDs are unique across every candidate
443	// (including disabled and filtered-out clusters), and tag/condition keys
444	// are non-empty. Errors name the field and the position in its list; within
445	// a cluster the ID is checked before its tags, and tag keys are examined in
446	// ascending order so repeated calls report the same error. The input is
447	// never mutated. MakeReleasePlan calls this automatically; library callers
448	// may use it to validate without planning.
449	func ValidateReleaseInput(in ReleasePlanInput) error {
450		if err := validateStrictText(in); err != nil {
451			return err
452		}
453		if strings.TrimSpace(in.App) == "" {
454			return errors.New(`字段 "app" 不能为空或只含空白`)
455		}
456		if strings.TrimSpace(in.Revision) == "" {
457			return errors.New(`字段 "revision" 不能为空或只含空白`)
458		}
459		if strings.TrimSpace(in.Image) == "" {
460			return errors.New(`字段 "image" 不能为空或只含空白`)
461		}
462		if in.BatchSize <= 0 {
463			return errors.New(`字段 "batchSize" 必须是正整数`)
464		}
465		if err := checkSpreadBy(in.SpreadBy); err != nil {
466			return err
467		}
468		ids := newClusterIDSet(len(in.Clusters))
469		for i, c := range in.Clusters {
470			if err := ids.check(i, c.ID); err != nil {
471				return err
472			}
473			if err := validateTagKeys(i, c.Tags); err != nil {
474				return err
475			}
476		}
477		if err := validateConditionKeys("include", in.Include); err != nil {
478			return err
479		}
480		if err := validateConditionKeys("exclude", in.Exclude); err != nil {
481			return err
482		}
483		return nil
484	}
485	
486	// validateTagKeys applies the shared label-key rule to one cluster's tags,
487	// reporting the cluster's position in the candidate list.
488	func validateTagKeys(clusterIndex int, tags map[string]string) error {
489		if hasEmptyLabelKey(tags) {
490			return fmt.Errorf("clusters[%d] 的标签键不能为空", clusterIndex)
491		}
492		return nil
493	}
494	
495	// validateConditionKeys applies the shared condition rules to every condition
496	// in original order, so the first invalid condition is reported.
497	func validateConditionKeys(field string, conds []LabelCondition) error {
498		for i, cond := range conds {
499			if err := validateCondition(field, i, cond); err != nil {
500				return err
501			}
502		}
503		return nil
504	}
505	
506	func requiredString(doc map[string]any, field string) (string, error) {
507		v, ok := doc[field]
508		if !ok {
509			return "", fmt.Errorf("缺少必需字段 %q", field)
510		}
511		s, ok := v.(string)
512		if !ok {
513			return "", fmt.Errorf("字段 %q 必须是字符串", field)
514		}
515		if strings.TrimSpace(s) == "" {
516			return "", fmt.Errorf("字段 %q 不能为空或只含空白", field)
517		}
518		return s, nil
519	}
520	
521	// positiveInt reads a required field as a positive integer. The literal must
522	// be an integral JSON number whose value is representable in full by the Go
523	// int of the running environment: a value beyond math.MaxInt is rejected here
524	// rather than narrowed by an int() conversion, which on a 32-bit environment
525	// could turn 4294967297 into 1 (or a larger value into zero or a negative
526	// number). No truncation, rounding, default substitution or clamping to the
527	// maximum ever happens — such a value is a configuration error regardless of
528	// what int it would collapse into.
529	func positiveInt(doc map[string]any, field string) (int, error) {
530		v, ok := doc[field]
531		if !ok {
532			return 0, fmt.Errorf("缺少必需字段 %q", field)
533		}
534		n, ok := v.(json.Number)
535		if !ok {
536			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
537		}
538		i, err := n.Int64()
539		if err != nil || i <= 0 || i > math.MaxInt {
540			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
541		}
542		return int(i), nil
543	}
544	
545	func parseClusters(v any) ([]Cluster, error) {
546		if v == nil {
547			return nil, errors.New("缺少必需字段 \"clusters\"")
548		}
549		raw, ok := v.([]any)
550		if !ok {
551			return nil, errors.New("字段 \"clusters\" 必须是数组")
552		}
553		clusters := make([]Cluster, 0, len(raw))
554		ids := newClusterIDSet(len(raw))
555		for i, item := range raw {
556			obj, ok := item.(map[string]any)
557			if !ok {
558				return nil, fmt.Errorf("clusters[%d] 必须是对象", i)
559			}
560			id, err := clusterIDFromJSON(obj, i, ids)
561			if err != nil {
562				return nil, err
563			}
564	
565			disabled := false
566			if dv, present := obj["disabled"]; present {
567				b, ok := dv.(bool)
568				if !ok {
569					return nil, fmt.Errorf("集群 %q 的 \"disabled\" 必须是布尔值", id)
570				}
571				disabled = b
572			}
573	
574			tags := map[string]string{}
575			if tv, present := obj["tags"]; present {
576				tm, ok := tv.(map[string]any)
577				if !ok {
578					return nil, fmt.Errorf("集群 %q 的 \"tags\" 必须是对象", id)
579				}
580				tags, err = labelsFromJSON(tm,
581					func(string) error { return fmt.Errorf("集群 %q 的标签键不能为空", id) },
582					func(k string) error { return fmt.Errorf("集群 %q 的标签 %q 值必须是字符串", id, k) },
583				)
584				if err != nil {
585					return nil, err
586				}
587			}
588	
589			clusters = append(clusters, Cluster{ID: id, Disabled: disabled, Tags: tags})
590		}
591		return clusters, nil
592	}
593	
594	// clusterIDFromJSON reads the "id" member of one candidate object and applies
595	// the shared cluster-identity rule. A missing member or a non-string value is
596	// a JSON decoding problem with its own reason; an empty or duplicate ID is
597	// reported by the shared rule exactly as for a directly constructed config.
598	func clusterIDFromJSON(obj map[string]any, index int, ids *clusterIDSet) (string, error) {
599		v, ok := obj["id"]
600		if !ok {
601			return "", fmt.Errorf("clusters[%d]: 缺少必需字段 %q", index, "id")
602		}
603		id, ok := v.(string)
604		if !ok {
605			return "", fmt.Errorf("clusters[%d]: 字段 %q 必须是字符串", index, "id")
606		}
607		if err := ids.check(index, id); err != nil {
608			return "", err
609		}
610		return id, nil
611	}
612	
613	// parseConditions reads the optional include/exclude field from the decoded
614	// document. An absent field means "no conditions" (the same as an explicit
615	// empty array); a field that is present must be an array of condition
616	// objects. An explicit JSON null is a field type error — it must not be read
617	// as "no conditions", which would silently drop the filter the author wrote.
618	func parseConditions(doc map[string]any, field string) ([]LabelCondition, error) {
619		v, ok := doc[field]
620		if !ok {
621			return []LabelCondition{}, nil
622		}
623		raw, ok := v.([]any)
624		if !ok {
625			return nil, fmt.Errorf("字段 %q 必须是条件数组", field)
626		}
627		conds := make([]LabelCondition, 0, len(raw))
628		for i, item := range raw {
629			obj, ok := item.(map[string]any)
630			if !ok {
631				return nil, fmt.Errorf("%s[%d] 必须是对象", field, i)
632			}
633			cond, err := labelsFromJSON(obj,
634				func(string) error { return fmt.Errorf("%s[%d] 的标签键不能为空", field, i) },
635				func(k string) error { return fmt.Errorf("%s[%d] 的标签 %q 值必须是字符串", field, i, k) },
636			)
637			if err != nil {
638				return nil, err
639			}
640			if err := validateCondition(field, i, cond); err != nil {
641				return nil, err
642			}
643			conds = append(conds, cond)
644		}
645		return conds, nil
646	}
647	
648	// MakeReleasePlan selects available clusters, orders them by ID, and splits
649	// them into batches. When SpreadBy names a tag, each batch holds at most one
650	// cluster per value of that tag (its fault domain) and every selected cluster
651	// must carry the tag. It validates the input first and never mutates it.
652	//
653	// When every candidate is filtered out, the returned error lists each
654	// candidate's rejection reason on its own line, ascending by the original
655	// ID. An ID containing a double quote, backslash, control character or
656	// U+2028/U+2029 is displayed as a quoted JSON string with those characters
657	// escaped (see rejectreport.go), so one candidate always occupies exactly
658	// one line and the original ID can be recovered from the display; this is
659	// only a display spelling — the ID itself is never altered or re-compared.
660	func MakeReleasePlan(in ReleasePlanInput) (ReleasePlan, error) {
661		if err := ValidateReleaseInput(in); err != nil {
662			return ReleasePlan{}, err
663		}
664		if len(in.Clusters) == 0 {
665			return ReleasePlan{}, errors.New("没有可发布的集群：未提供候选集群")
666		}
667	
668		selected := []string{}
669		excluded := []ExcludedCluster{}
670		for _, c := range in.Clusters {
671			switch {
672			case c.Disabled:
673				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonDisabled})
674			case matchesAny(c.Tags, in.Exclude):
675				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonExcludeMatched})
676			case len(in.Include) > 0 && !matchesAny(c.Tags, in.Include):
677				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonIncludeNotMatched})
678			default:
679				selected = append(selected, c.ID)
680			}
681		}
682	
683		sort.Strings(selected)
684		sort.Slice(excluded, func(i, j int) bool { return excluded[i].ID < excluded[j].ID })
685	
686		if len(selected) == 0 {
687			var b strings.Builder
688			b.WriteString("没有符合规则的可用集群，各候选集群未入选原因：")
689			for _, e := range excluded {
690				b.WriteString("\n  ")
691				b.WriteString(reportClusterID(e.ID))
692				b.WriteString("：")
693				b.WriteString(e.Reason)
694			}
695			return ReleasePlan{}, errors.New(b.String())
696		}
697	
698		var batches []Batch
699		if in.SpreadBy == "" {
700			batches = chunkBatches(selected, in.BatchSize)
701		} else {
702			domains, err := faultDomains(in.Clusters, selected, in.SpreadBy)
703			if err != nil {
704				return ReleasePlan{}, err
705			}
706			batches = spreadBatches(selected, domains, in.BatchSize)
707		}
708	
709		return ReleasePlan{
710			App:      AppInfo{Name: in.App, Revision: in.Revision, Image: in.Image},
711			Batches:  batches,
712			Excluded: excluded,
713		}, nil
714	}
715	
716	// chunkBatches splits the ascending IDs into batches of at most batchSize.
717	// Each batch's Clusters gets its own backing array: a subslice of selected
718	// would leave spare capacity pointing at the next batch's IDs, so a caller
719	// appending to one batch's list would overwrite the following batch.
720	func chunkBatches(selected []string, batchSize int) []Batch {
721		batches := []Batch{}
722		for i := 0; i < len(selected); i += batchSize {
723			end := i + batchSize
724			if end > len(selected) {
725				end = len(selected)
726			}
727			clusters := make([]string, end-i)
728			copy(clusters, selected[i:end])
729			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: clusters})
730		}
731		return batches
732	}
733	
734	// faultDomains maps every selected cluster ID to the exact value of its
735	// spreadBy tag. A selected cluster missing the tag fails the whole plan;
736	// selected is ascending, so the smallest such ID is reported. An empty
737	// string tag value is a valid fault domain, distinct from a missing tag.
738	func faultDomains(clusters []Cluster, selected []string, spreadBy string) (map[string]string, error) {
739		tagsByID := make(map[string]map[string]string, len(clusters))
740		for _, c := range clusters {
741			tagsByID[c.ID] = c.Tags
742		}
743		domains := make(map[string]string, len(selected))
744		for _, id := range selected {
745			v, ok := tagsByID[id][spreadBy]
746			if !ok {
747				return nil, fmt.Errorf("集群 %q 缺少故障域标签 %q", id, spreadBy)
748			}
749			domains[id] = v
750		}
751		return domains, nil
752	}
753	
754	// spreadBatches packs the ascending IDs into batches of at most batchSize
755	// with at most one cluster per fault domain in each batch. Each batch takes
756	// the smallest still-unscheduled IDs whose domains do not conflict with the
757	// batch; conflicting clusters are deferred to later batches, so a batch may
758	// be short only when no non-conflicting cluster remains. Every ID appears in
759	// exactly one batch and IDs stay ascending within a batch.
760	func spreadBatches(selected []string, domains map[string]string, batchSize int) []Batch {
761		remaining := append([]string(nil), selected...)
762		batches := []Batch{}
763		for len(remaining) > 0 {
764			// The map never holds more entries than there are remaining clusters,
765			// so size it by them — never by batchSize, which is only an upper
766			// bound and may be a huge legal value (e.g. 1e9 meaning "no limit").
767			used := make(map[string]struct{}, min(batchSize, len(remaining)))
768			batch := []string{}
769			deferred := []string{}
770			for _, id := range remaining {
771				d := domains[id]
772				if _, conflict := used[d]; len(batch) < batchSize && !conflict {
773					used[d] = struct{}{}
774					batch = append(batch, id)
775				} else {
776					deferred = append(deferred, id)
777				}
778			}
779			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: batch})
780			remaining = deferred
781		}
782		return batches
783	}
784	
785	func matchesAny(tags map[string]string, conditions []LabelCondition) bool {
786		for _, cond := range conditions {
787			if matchesAll(tags, cond) {
788				return true
789			}
790		}
791		return false
792	}
793	
794	func matchesAll(tags map[string]string, cond LabelCondition) bool {
795		for k, v := range cond {
796			tv, ok := tags[k]
797			if !ok || tv != v {
798				return false
799			}
800		}
801		return true
802	}
803

