92			for _, id := range b.Clusters {
93				if prev, dup := seen[id]; dup {
94					t.Fatalf("cluster %q appears in batch %d and again in batch %d", id, prev, i+1)
95				}
96				seen[id] = i + 1
97				d, known := domains[id]
98				if !known {
