1	package darksafe
2	
3	import (
4		"maps"
5		"reflect"
6		"strings"
7		"testing"
8	)
9	
10	// This file is a regression net for the documented failure-return contract of
11	// MakeReleasePlan driven the library way: a ReleasePlanInput constructed
12	// directly in memory — no JSON document and no command line in between. The
13	// README promises that MakeReleasePlan hands over a complete plan only on
14	// success; on every failure it returns non-nil error together with the ZERO
15	// ReleasePlan. These tests therefore assert only what a caller actually
16	// observes — the returned plan, the returned error and the untouched input —
17	// never how the planner organizes its intermediate selection.
18	
19	// assertZeroReleasePlan checks that a failed call leaked no partial result:
20	// no app info, no batches and not even the excluded list computed during
21	// filtering are returned.
22	func assertZeroReleasePlan(t *testing.T, plan ReleasePlan) {
23		t.Helper()
24		if plan.App != (AppInfo{}) {
25			t.Fatalf("failure must not return partial app info, got %+v", plan.App)
26		}
27		if plan.Batches != nil {
28			t.Fatalf("failure must not return partial batches, got %+v", plan.Batches)
29		}
30		if plan.Excluded != nil {
31			t.Fatalf("failure must not return a partial excluded list, got %+v", plan.Excluded)
32		}
33		if !reflect.DeepEqual(plan, ReleasePlan{}) {
34			t.Fatalf("failure must return the zero-value ReleasePlan, got %+v", plan)
35		}
36	}
37	
38	// allRejectedLibraryError renders the exact library error for a fully rejected
39	// plan: the summary line followed by one "  <id>：<reason>" line per
40	// candidate, ascending by ID. Unlike the CLI variant there is no trailing
41	// newline — the error is returned, not Fprintln'ed.
42	func allRejectedLibraryError(entries ...string) string {
43		var b strings.Builder
44		b.WriteString("没有符合规则的可用集群，各候选集群未入选原因：")
45		for _, e := range entries {
46			b.WriteString("\n  ")
47			b.WriteString(e)
48		}
49		return b.String()
50	}
51	
52	// allRejectedMixedInput builds an in-memory config in which filtering has run
53	// and produced results — every rejection reason occurs, and the fixed
54	// disabled → exclude → include priority is observable in one shared error:
55	//   - c-both matches both the include (env=prod) and an exclude
56	//     (quarantine=true) condition: exclude wins;
57	//   - c-temp matches an exclude condition: rejected even though it would also
58	//     fail the include check;
59	//   - c-off is disabled AND matches an exclude condition: disabled wins;
60	//   - c-dev matches no include condition.
61	//
62	// SpreadBy is enabled while NONE of these clusters carries the zone tag; the
63	// all-rejected failure must still report the filter reasons rather than turn
64	// into a missing-fault-domain-tag error. The permutation arguments reorder the
65	// candidates to prove none of this depends on input order.
66	func allRejectedMixedInput(order string) ReleasePlanInput {
67		in := ReleasePlanInput{
68			App:       "app",
69			Revision:  "r1",
70			Image:     "img",
71			BatchSize: 2,
72			SpreadBy:  "zone",
73			Include:   []LabelCondition{{"env": "prod"}},
74			Exclude:   []LabelCondition{{"env": "temp"}, {"quarantine": "true"}},
75		}
76		candidates := map[string][]Cluster{
77			"a": {
78				{ID: "c-both", Tags: map[string]string{"env": "prod", "quarantine": "true"}},
79				{ID: "c-dev", Tags: map[string]string{"env": "dev"}},
80				{ID: "c-off", Disabled: true, Tags: map[string]string{"env": "temp"}},
81				{ID: "c-temp", Tags: map[string]string{"env": "temp"}},
82			},
83			"b": {
84				{ID: "c-temp", Tags: map[string]string{"env": "temp"}},
85				{ID: "c-off", Disabled: true, Tags: map[string]string{"env": "temp"}},
86				{ID: "c-dev", Tags: map[string]string{"env": "dev"}},
87				{ID: "c-both", Tags: map[string]string{"quarantine": "true", "env": "prod"}},
88			},
89		}
90		in.Clusters = candidates[order]
91		return in
92	}
93	
94	// wantAllRejectedMixedError is the complete, exact error for
95	// allRejectedMixedInput: every candidate exactly once, ascending by ID with
96	// the reason the priority rules dictate.
97	func wantAllRejectedMixedError() string {
98		return allRejectedLibraryError(
99			"c-both："+ReasonExcludeMatched,
100			"c-dev："+ReasonIncludeNotMatched,
101			"c-off："+ReasonDisabled,
102			"c-temp："+ReasonExcludeMatched,
103		)
104	}
105	
106	// TestMakeReleasePlan_AllRejectedReturnsZeroPlanWithReasons covers the
107	// "filtering produced results but no plan can be delivered" failure directly
108	// from an in-memory config: all four candidates are filtered out (one per
109	// reason/priority interaction) while spreadBy is enabled and none has the
110	// spread tag. The call must return a non-nil error carrying every candidate's
111	// reason ascending by ID, and the zero-value plan — app info, batches and the
112	// excluded list must not come back as partial results.
113	func TestMakeReleasePlan_AllRejectedReturnsZeroPlanWithReasons(t *testing.T) {
114		in := allRejectedMixedInput("a")
115		plan, err := MakeReleasePlan(in)
116		if err == nil {
117			t.Fatal("expected a non-nil error when every candidate is filtered out")
118		}
119		assertZeroReleasePlan(t, plan)
120	
121		msg := err.Error()
122		if msg != wantAllRejectedMixedError() {
123			t.Fatalf("rejection error mismatch:\n got %q\nwant %q", msg, wantAllRejectedMixedError())
124		}
125		// The filter failure must not be replaced by the fault-domain check:
126		// filtered-out clusters need no spreadBy tag.
127		if strings.Contains(msg, "故障域") || strings.Contains(msg, "缺少") {
128			t.Fatalf("all-rejected failure must report filter reasons, got %q", msg)
129		}
130	}
131	
132	// TestMakeReleasePlan_AllRejectedOrderIndependent runs the same configuration
133	// with candidates written in a different order: the error and the zero plan
134	// must be identical.
135	func TestMakeReleasePlan_AllRejectedOrderIndependent(t *testing.T) {
136		planA, errA := MakeReleasePlan(allRejectedMixedInput("a"))
137		planB, errB := MakeReleasePlan(allRejectedMixedInput("b"))
138		if errA == nil || errB == nil {
139			t.Fatal("both permutations must fail")
140		}
141		if errA.Error() != errB.Error() {
142			t.Fatalf("candidate order changed the error:\n a: %q\n b: %q", errA.Error(), errB.Error())
143		}
144		if errA.Error() != wantAllRejectedMixedError() {
145			t.Fatalf("unexpected error: %q", errA.Error())
146		}
147		assertZeroReleasePlan(t, planA)
148		assertZeroReleasePlan(t, planB)
149	}
150	
151	// missingSpreadTagInput builds an in-memory config where selection already has
152	// results on both sides: s-a is selected and carries the zone tag; s-b is
153	// selected but lacks it; x-off (disabled) and x-dev (fails the include
154	// condition) are filtered out and ALSO lack the tag. Planning must fail on
155	// s-b only — a filtered cluster's missing tag must never preempt the error.
156	func missingSpreadTagInput(order string) ReleasePlanInput {
157		in := ReleasePlanInput{
158			App:       "app",
159			Revision:  "r1",
160			Image:     "img",
161			BatchSize: 2,
162			SpreadBy:  "zone",
163			Include:   []LabelCondition{{"env": "prod"}},
164		}
165		candidates := map[string][]Cluster{
166			"a": {
167				{ID: "s-a", Tags: map[string]string{"env": "prod", "zone": "z1"}},
168				{ID: "s-b", Tags: map[string]string{"env": "prod"}},
169				{ID: "x-off", Disabled: true},
170				{ID: "x-dev", Tags: map[string]string{"env": "dev"}},
171			},
172			"b": {
173				{ID: "x-dev", Tags: map[string]string{"env": "dev"}},
174				{ID: "s-b", Tags: map[string]string{"env": "prod"}},
175				{ID: "x-off", Disabled: true},
176				{ID: "s-a", Tags: map[string]string{"zone": "z1", "env": "prod"}},
177			},
178		}
179		in.Clusters = candidates[order]
180		return in
181	}
182	
183	// TestMakeReleasePlan_SelectedMissingSpreadTagReturnsZeroPlan covers the
184	// "some clusters selected, some excluded, but a selected cluster lacks the
185	// spreadBy tag" failure: the whole computation fails with the zero-value plan,
186	// and the error names the missing tag and the smallest offending selected
187	// cluster. Filtered-out clusters that also lack the tag must not be reported
188	// instead, and candidate input order must not change anything.
189	func TestMakeReleasePlan_SelectedMissingSpreadTagReturnsZeroPlan(t *testing.T) {
190		const wantErr = `集群 "s-b" 缺少故障域标签 "zone"`
191		for _, order := range []string{"a", "b"} {
192			t.Run("order-"+order, func(t *testing.T) {
193				plan, err := MakeReleasePlan(missingSpreadTagInput(order))
194				if err == nil {
195					t.Fatal("expected a non-nil error for the missing spread tag")
196				}
197				assertZeroReleasePlan(t, plan)
198				if err.Error() != wantErr {
199					t.Fatalf("error = %q, want %q", err.Error(), wantErr)
200				}
201				// The error must name the tag key and the smallest selected
202				// offender, and never a cluster filtered out earlier.
203				msg := err.Error()
204				if !strings.Contains(msg, `"s-b"`) || !strings.Contains(msg, `"zone"`) {
205					t.Fatalf("error must name s-b and the zone tag, got %q", msg)
206				}
207				if strings.Contains(msg, "x-off") || strings.Contains(msg, "x-dev") {
208					t.Fatalf("filtered-out clusters must not preempt the error, got %q", msg)
209				}
210			})
211		}
212	}
213	
214	// TestMakeReleasePlan_MissingSpreadTagReportsSmallestCluster selects several
215	// clusters, two of which lack the tag: regardless of input order, the error
216	// names m-a — the smallest ID among selected offenders — and only that one.
217	func TestMakeReleasePlan_MissingSpreadTagReportsSmallestCluster(t *testing.T) {
218		build := func(order string) ReleasePlanInput {
219			in := ReleasePlanInput{
220				App: "app", Revision: "r1", Image: "img", BatchSize: 2, SpreadBy: "zone",
221			}
222			candidates := map[string][]Cluster{
223				"a": {
224					{ID: "m-c", Tags: map[string]string{"zone": "z2"}},
225					{ID: "m-a"},
226					{ID: "m-b", Tags: map[string]string{}},
227				},
228				"b": {
229					{ID: "m-b", Tags: map[string]string{}},
230					{ID: "m-c", Tags: map[string]string{"zone": "z2"}},
231					{ID: "m-a"},
232				},
233			}
234			in.Clusters = candidates[order]
235			return in
236		}
237		const wantErr = `集群 "m-a" 缺少故障域标签 "zone"`
238		for _, order := range []string{"a", "b"} {
239			plan, err := MakeReleasePlan(build(order))
240			if err == nil {
241				t.Fatalf("order %s: expected error", order)
242			}
243			assertZeroReleasePlan(t, plan)
244			if err.Error() != wantErr {
245				t.Fatalf("order %s: error = %q, want %q", order, err.Error(), wantErr)
246			}
247		}
248	}
249	
250	// TestMakeReleasePlan_EmptyStringSpreadTagSucceeds is the success control for
251	// the missing-tag failure above: a tag PRESENT with an empty string value is a
252	// legal fault domain and must not be mistaken for a missing tag. Two
253	// empty-domain clusters avoid each other across batches, a disabled cluster
254	// without the tag is filtered out, and a complete plan is returned.
255	func TestMakeReleasePlan_EmptyStringSpreadTagSucceeds(t *testing.T) {
256		in := ReleasePlanInput{
257			App:       "app",
258			Revision:  "r1",
259			Image:     "img",
260			BatchSize: 2,
261			SpreadBy:  "zone",
262			Include:   []LabelCondition{{"env": "prod"}},
263			Clusters: []Cluster{
264				{ID: "a", Tags: map[string]string{"env": "prod", "zone": ""}},
265				{ID: "b", Tags: map[string]string{"env": "prod", "zone": ""}},
266				{ID: "c", Tags: map[string]string{"env": "prod", "zone": "east"}},
267				{ID: "x", Disabled: true, Tags: map[string]string{"env": "prod"}},
268			},
269		}
270		plan, err := MakeReleasePlan(in)
271		if err != nil {
272			t.Fatalf("an empty-string tag value is a valid domain: %v", err)
273		}
274		if got := batchIDs(plan); strings.Join(got, "|") != "a,c|b" {
275			t.Fatalf("batches = %v, want [a c]|[b]", got)
276		}
277		if len(plan.Excluded) != 1 || plan.Excluded[0] != (ExcludedCluster{ID: "x", Reason: ReasonDisabled}) {
278			t.Fatalf("excluded = %+v, want x: %s", plan.Excluded, ReasonDisabled)
279		}
280	}
281	
282	// TestMakeReleasePlan_ConfigValidationFailureReturnsZeroPlan checks that
283	// front-loaded config validation obeys the same failure convention. The focus
284	// case is a duplicate cluster ID where the SECOND record is disabled: identity
285	// is checked before any disabled/filter decision, so MakeReleasePlan must
286	// surface the configuration error first (never silently plan with the first
287	// record), ValidateReleaseInput must reject it on its own, and the returned
288	// plan is the zero value.
289	func TestMakeReleasePlan_ConfigValidationFailureReturnsZeroPlan(t *testing.T) {
290		dup := ReleasePlanInput{
291			App:       "app",
292			Revision:  "r1",
293			Image:     "img",
294			BatchSize: 2,
295			SpreadBy:  "zone",
296			Clusters: []Cluster{
297				{ID: "dup", Tags: map[string]string{"env": "prod", "zone": "z1"}},
298				{ID: "dup", Disabled: true},
299			},
300		}
301		verr := ValidateReleaseInput(dup)
302		if verr == nil {
303			t.Fatal("ValidateReleaseInput must reject the duplicate, even inside a disabled record")
304		}
305		if !strings.Contains(verr.Error(), `clusters[1]`) || !strings.Contains(verr.Error(), `重复的集群标识 "dup"`) {
306			t.Fatalf("validation error must name position 1 and the duplicated id, got %v", verr)
307		}
308	
309		plan, err := MakeReleasePlan(dup)
310		if err == nil {
311			t.Fatal("MakeReleasePlan must fail with a config error")
312		}
313		if err.Error() != verr.Error() {
314			t.Fatalf("MakeReleasePlan must report the config error first:\n plan: %q\nvalidate: %q", err, verr)
315		}
316		assertZeroReleasePlan(t, plan)
317		if strings.Contains(err.Error(), "未提供候选集群") || strings.Contains(err.Error(), "故障域") {
318			t.Fatalf("config error must not be masked by a planning failure, got %q", err)
319		}
320	
321		// Other pre-validation failures keep the same zero-plan convention.
322		for name, mutate := range map[string]func(*ReleasePlanInput){
323			"app empty":      func(in *ReleasePlanInput) { in.App = "" },
324			"batch zero":     func(in *ReleasePlanInput) { in.BatchSize = 0 },
325			"empty tag key":  func(in *ReleasePlanInput) { in.Clusters[0].Tags = map[string]string{"": "v"} },
326			"whitespace sid": func(in *ReleasePlanInput) { in.SpreadBy = "  " },
327		} {
328			t.Run(name, func(t *testing.T) {
329				in := validInput()
330				mutate(&in)
331				p, merr := MakeReleasePlan(in)
332				if merr == nil {
333					t.Fatalf("expected error for %s", name)
334				}
335				assertZeroReleasePlan(t, p)
336			})
337		}
338	}
339	
340	// cloneInput returns a deep copy of the caller-owned parts of a config
341	// (candidate order, cluster tags and include/exclude conditions), so a test
342	// can prove a failed computation left the original byte-for-byte unchanged.
343	func cloneInput(in ReleasePlanInput) ReleasePlanInput {
344		cp := in
345		cp.Clusters = append([]Cluster(nil), in.Clusters...)
346		for i := range cp.Clusters {
347			cp.Clusters[i].Tags = maps.Clone(in.Clusters[i].Tags)
348		}
349		cp.Include = cloneConditions(in.Include)
350		cp.Exclude = cloneConditions(in.Exclude)
351		return cp
352	}
353	
354	func cloneConditions(conds []LabelCondition) []LabelCondition {
355		if conds == nil {
356			return nil
357		}
358		out := make([]LabelCondition, len(conds))
359		for i, cond := range conds {
360			out[i] = maps.Clone(cond)
361		}
362		return out
363	}
364	
365	// candidateIDs returns the candidate IDs in the exact order the caller passed
366	// them.
367	func candidateIDs(in ReleasePlanInput) []string {
368		ids := make([]string, len(in.Clusters))
369		for i, c := range in.Clusters {
370			ids[i] = c.ID
371		}
372		return ids
373	}
374	
375	// TestMakeReleasePlan_FailureDoesNotMutateInput runs every failure shape and
376	// checks the caller's config is untouched: candidate order is preserved, and
377	// neither cluster tags nor include/exclude conditions are rewritten — even
378	// though the planner sorts and inspects them internally.
379	func TestMakeReleasePlan_FailureDoesNotMutateInput(t *testing.T) {
380		cases := map[string]ReleasePlanInput{
381			"all rejected":       allRejectedMixedInput("b"),
382			"missing spread tag": missingSpreadTagInput("b"),
383			"no candidates": {
384				App: "app", Revision: "r1", Image: "img", BatchSize: 2,
385				SpreadBy: "zone",
386				Include:  []LabelCondition{{"env": "prod"}},
387				Exclude:  []LabelCondition{{"env": "temp"}},
388			},
389			"duplicate disabled id": {
390				App: "app", Revision: "r1", Image: "img", BatchSize: 2,
391				Clusters: []Cluster{
392					{ID: "dup", Tags: map[string]string{"env": "prod"}},
393					{ID: "dup", Disabled: true, Tags: map[string]string{"env": "temp"}},
394				},
395			},
396		}
397		for name, in := range cases {
398			t.Run(name, func(t *testing.T) {
399				before := cloneInput(in)
400				orderBefore := candidateIDs(in)
401				plan, err := MakeReleasePlan(in)
402				if err == nil {
403					t.Fatal("expected a failed computation")
404				}
405				assertZeroReleasePlan(t, plan)
406				if got := candidateIDs(in); !reflect.DeepEqual(got, orderBefore) {
407					t.Fatalf("candidate order changed: %v -> %v", orderBefore, got)
408				}
409				if !reflect.DeepEqual(in, before) {
410					t.Fatalf("failed computation mutated the input:\n before: %#v\n after:  %#v", before, in)
411				}
412			})
413		}
414	}
415	
416	// TestValidate_EmptyCandidatesKeepsOperationsDistinct pins the distinction
417	// between the two public operations when every other field is legal: standalone
418	// validation SUCCEEDS on an empty candidate list (the config is well-formed),
419	// while actually planning fails with "未提供候选集群" and the zero-value plan.
420	// Both nil and a non-nil empty slice are empty candidate lists.
421	func TestValidate_EmptyCandidatesKeepsOperationsDistinct(t *testing.T) {
422		for name, clusters := range map[string][]Cluster{"nil slice": nil, "empty slice": {}} {
423			t.Run(name, func(t *testing.T) {
424				in := ReleasePlanInput{
425					App:       "app",
426					Revision:  "r1",
427					Image:     "img",
428					BatchSize: 2,
429					SpreadBy:  "zone",
430					Include:   []LabelCondition{{"env": "prod"}},
431					Exclude:   []LabelCondition{{"env": "temp"}},
432					Clusters:  clusters,
433				}
434				if err := ValidateReleaseInput(in); err != nil {
435					t.Fatalf("validation alone must succeed with legal fields and no candidates, got %v", err)
436				}
437				plan, err := MakeReleasePlan(in)
438				if err == nil {
439					t.Fatal("planning with no candidates must fail")
440				}
441				if !strings.Contains(err.Error(), "没有可发布的集群：未提供候选集群") {
442					t.Fatalf("expected the no-candidate error, got %q", err.Error())
443				}
444				// This is distinct from the all-rejected failure, which lists
445				// per-candidate reasons.
446				if strings.Contains(err.Error(), "未入选原因") {
447					t.Fatalf("no-candidate error must not look like an all-rejected error: %q", err)
448				}
449				assertZeroReleasePlan(t, plan)
450			})
451		}
452	}
