2	
3	import (
4		"fmt"
5		"unicode/utf8"
6	)
7	
8	// This file extends the strict-text rule (see stricttext.go for the JSON
9	// entry) to a release configuration constructed directly in Go memory and
10	// handed to ValidateReleaseInput or MakeReleasePlan.
11	//
12	// A Go string can hold bytes that are not valid UTF-8. Without this check
13	// such bytes would survive into planning unchanged at first, but two
14	// distinct corrupt identities would be indistinguishable the moment the
15	// plan is written as JSON — encoding/json rewrites every invalid rune to
16	// the replacement character "�" (U+FFFD) — and corrupt tag keys or values
17	// would silently take part in label matching and fault-domain batching. The
18	// check therefore runs as the first stage of ValidateReleaseInput, before
19	// any business rule and hence before selection or batching: the config is
20	// rejected outright rather than producing a plan that looks successful.
21	//
22	// Legal text is used exactly as written — including Chinese, supplementary
23	// plane characters such as "😀", and a literally written "�" — and ordinary
24	// text that merely contains a backslash followed by "uD800" is not invalid
25	// UTF-8 (only the JSON entry deals with \uXXXX escapes at all).
26	//
27	// When several strings are invalid, exactly one deterministic problem is
28	// reported. Scalars are checked in their fixed field order; candidates and
29	// conditions at their real zero-based positions (disabled clusters and
30	// clusters that filtering would drop are checked just the same); within one
31	// tags object or condition the entries are examined in ascending key order,
32	// so map iteration order can never change the error. Cluster tags and
33	// include/exclude conditions are all checked by the one shared label-set
34	// rule (checkStrictLabelText); only the error wording differs per object. A
35	// value error names the key it belongs to; an invalid key names the tags
36	// object or condition object owning it.
37	
38	// invalidConfigTextError reports a string in a directly constructed config
39	// that contains bytes which are not valid UTF-8. where is a field-and-
40	// position description in the same style as the business-validation errors:
41	// a top-level field for scalars, clusters[i] (plus the offending tag key or
42	// the owning tags object) for candidate data, and include[i]/exclude[i]
43	// (plus the condition key or owning condition object) for conditions.
44	type invalidConfigTextError struct {
45		where string
46	}
47	
48	func (e *invalidConfigTextError) Error() string {
49		return fmt.Sprintf("内存配置包含无效 UTF-8 字节: %s", e.where)
50	}
51	
52	// validateStrictText rejects invalid UTF-8 anywhere in a Go-constructed
53	// config, in a fixed order independent of map iteration: app, revision,
54	// image, spreadBy, then every candidate (ID before its tags, tags in
55	// ascending key order), then every include and exclude condition in list
56	// order (entries likewise in ascending key order). The input is only read.
57	func validateStrictText(in ReleasePlanInput) error {
58		if !utf8.ValidString(in.App) {
59			return &invalidConfigTextError{where: `字段 "app"`}
60		}
61		if !utf8.ValidString(in.Revision) {
62			return &invalidConfigTextError{where: `字段 "revision"`}
63		}
64		if !utf8.ValidString(in.Image) {
65			return &invalidConfigTextError{where: `字段 "image"`}
66		}
67		if !utf8.ValidString(in.SpreadBy) {
68			return &invalidConfigTextError{where: `字段 "spreadBy"`}
69		}
70		for i, c := range in.Clusters {
71			if !utf8.ValidString(c.ID) {
72				return &invalidConfigTextError{where: fmt.Sprintf(`clusters[%d] 的字段 "id"`, i)}
73			}
74			if err := validateStrictTagText(i, c.Tags); err != nil {
75				return err
76			}
77		}
78		if err := validateStrictConditionText("include", in.Include); err != nil {
79			return err
80		}
81		if err := validateStrictConditionText("exclude", in.Exclude); err != nil {
82			return err
83		}
84		return nil
85	}
86	
87	// checkStrictLabelText is the one UTF-8 rule every label set in a Go-built
88	// config is held to — a candidate's tags and each include/exclude condition
89	// alike, so the same text is legal or illegal everywhere. Entries are
90	// examined in ascending key order; for each entry the key is checked before
91	// its value. The first invalid string is reported through keyErr (invalid
92	// key) or valueErr (invalid value), which format the error for the object
93	// owning the set — the same division of shared rule and per-context wording
94	// as labelsFromJSON. The set is only read.
95	func checkStrictLabelText(labels map[string]string, keyErr, valueErr func(key string) error) error {
96		for _, k := range sortedLabelKeys(labels) {
97			if !utf8.ValidString(k) {
98				return keyErr(k)
99			}
100			if !utf8.ValidString(labels[k]) {
101				return valueErr(k)
102			}
103		}
104		return nil
105	}
106	
107	// validateStrictTagText checks one candidate's tags at its zero-based
108	// candidate position. An invalid value is reported with the (valid) key it
109	// belongs to; an invalid key is quoted byte-for-byte (so the corrupt bytes
110	// are shown as Go-escaped octets rather than rewritten to "�") and reported
111	// as belonging to that candidate's tags object.
112	func validateStrictTagText(clusterIndex int, tags map[string]string) error {
113		return checkStrictLabelText(tags,
114			func(k string) error {
115				return &invalidConfigTextError{
116					where: fmt.Sprintf("clusters[%d] 的标签映射包含非法键 %q", clusterIndex, k),
117				}
118			},
119			func(k string) error {
120				return &invalidConfigTextError{
121					where: fmt.Sprintf("clusters[%d] 的标签键 %q 对应的值", clusterIndex, k),
122				}
123			},
124		)
125	}
126	
127	// validateStrictConditionText checks every condition of one field
128	// ("include" or "exclude") at its zero-based list position, applying the
129	// shared label-set text rule to each.
130	func validateStrictConditionText(field string, conds []LabelCondition) error {
131		for i, cond := range conds {
132			if err := checkStrictLabelText(cond,
133				func(k string) error {
134					return &invalidConfigTextError{
135						where: fmt.Sprintf("%s[%d] 的条件对象包含非法键 %q", field, i, k),
136					}
137				},
138				func(k string) error {
139					return &invalidConfigTextError{
140						where: fmt.Sprintf("%s[%d] 的条件键 %q 对应的值", field, i, k),
141					}
142				},
143			); err != nil {
144				return err
145			}
146		}
147		return nil
148	}
