// firstBatchDoc builds a plan document with the given batch capacities and
// cluster list; first is substituted as a raw JSON literal (use "" to omit
// the field entirely).
func firstBatchDoc(batchSize int, first string, clusters string) string {
	doc := `{"app":"app","revision":"r1","image":"img","batchSize":` +
		itoa(batchSize)
	if first != "" {
		doc += `,"firstBatchSize":` + first
	}
	return doc + `,"clusters":[` + clusters + `]}`
}

func itoa(n int) string {
	return strings.TrimSpace(strings.ReplaceAll(strings.Trim(strings.TrimPrefix(strings.TrimSuffix(strings.Repeat(" ", 0), ""), ""), " "), " ", "")) + intString(n)
}

// intString renders a small non-negative int without importing strconv in
// every helper call site.
func intString(n int) string {
	if n == 0 {
		return "0"
	}
	digits := []byte{}
	for n > 0 {
		digits = append([]byte{byte('0' + n%10)}, digits...)
		n /= 10
	}
	return string(digits)
}

